def parameter_schema():
    return copy.deepcopy(SCHEMA)


def _validate(value, schema, path):
    types = schema.get('type', [])
    types = [types] if isinstance(types, str) else types
    matches = {'null': value is None, 'boolean': type(value) is bool,
               'integer': type(value) is int, 'number': type(value) in (int, float),
               'string': isinstance(value, str), 'array': isinstance(value, list),
               'object': isinstance(value, dict)}
    if types and not any(matches.get(t, False) for t in types):
        raise ValueError(f'{path}: expected {types}')
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError(f'{path}: nonfinite number')
    if 'enum' in schema and value not in schema['enum']:
        raise ValueError(f'{path}: unsupported value {value!r}')
    if 'const' in schema and value != schema['const']:
        raise ValueError(f'{path}: fixed by checkpoint profile')
    if value is None:
        return
    if isinstance(value, str) and len(value) < schema.get('minLength', 0):
        raise ValueError(f'{path}: empty value')
    if type(value) in (int, float) and value < schema.get('minimum', -math.inf):
        raise ValueError(f'{path}: below native minimum')
    if isinstance(value, list):
        if len(value) < schema.get('minItems', 0):
            raise ValueError(f'{path}: empty list')
        for i, item in enumerate(value):
            _validate(item, schema.get('items', {}), f'{path}[{i}]')
    if isinstance(value, dict):
        props = schema.get('properties', {})
        additional = schema.get('additionalProperties', True)
        unknown = set(value) - set(props)
        if additional is False and unknown:
            raise ValueError(f'{path}: unknown settings {sorted(unknown)}')
        missing = set(schema.get('required', [])) - set(value)
        if missing:
            raise ValueError(f'{path}: missing settings {sorted(missing)}')
        for key, item in value.items():
            _validate(item, props.get(key, additional if isinstance(additional, dict) else {}), f'{path}.{key}')


def normalize_options(options):
    schema = {**SCHEMA, 'properties': {k:v for k,v in SCHEMA['properties'].items() if k != 'target_pdb'}, 'required': ['binder_chain']}
    result = copy.deepcopy(options)
    for key, spec in schema['properties'].items():
        if key not in result and 'default' in spec:
            result[key] = copy.deepcopy(spec['default'])
    criteria_props = SCHEMA['properties']['criteria']['items']['properties']
    if isinstance(result.get('criteria'), list):
        for criterion in result['criteria']:
            if isinstance(criterion, dict):
                for key, spec in criteria_props.items():
                    criterion.setdefault(key, copy.deepcopy(spec['default']))
    if isinstance(result.get('engine_options'), dict):
        for key, spec in schema['properties']['engine_options']['properties'].items():
            result['engine_options'].setdefault(key, copy.deepcopy(spec['default']))
    _validate(result, schema, 'options')
    # Same native combination checks, including native center_types normalization.
    result['criteria'] = [asdict(PHDesignCriteria(**item)) for item in result['criteria']]
    return result


def normalize_params(params):
    _validate(params, SCHEMA, 'params')
    return {'target_pdb': params['target_pdb'], **normalize_options({k:v for k,v in params.items() if k != 'target_pdb'})}


def normalize_request(request):
    if set(request) != {'contract', 'options', 'source'} or request['contract'] != CONTRACT:
        raise ValueError('Unknown ProtonPottsMPNN native contract')
    source = request['source']
    if not isinstance(source, dict) or set(source) != {'requested_path', 'sha256'}:
        raise ValueError('Invalid native source identity')
    if not isinstance(source['requested_path'], str) or not isinstance(source['sha256'], str) or len(source['sha256']) != 64 or any(c not in '0123456789abcdef' for c in source['sha256']):
        raise ValueError('Invalid native source identity')
    return {'contract': CONTRACT, 'options': normalize_options(request['options']), 'source': copy.deepcopy(source)}
